{
  "opening": "This release introduces several improvements to the humanize library, focusing on type safety, metric precision, and robustness in date/time formatting. It also addresses specific edge cases in number formatting and deprecates internal utilities to clean up the public API surface.",
  "requirements": [
    {
      "id": "m01",
      "text": "The functions Unit, abs_timedelta, date_and_delta, deactivate, gettext, gettext_noop, intword, naturaldate, naturaldelta, naturaltime, ngettext, ngettext_noop, num_name, pgettext, precisedelta, and thousands_separator must remain accessible as public API symbols."
    },
    {
      "id": "m03",
      "text": "The naturaldelta function must correctly handle duration strings involving years without truncating or misformatting them. The precisedelta function must accurately represent time intervals that span across year boundaries."
    },
    {
      "id": "m08",
      "text": "The naturaldelta function must not raise an overflow error when processing very large timedelta values. The naturaltime function must similarly avoid overflow errors when calculating relative times for distant past or future dates."
    },
    {
      "id": "m27",
      "text": "All listed public functions including Unit, activate, apnumber, clamp, deactivate, fractional, get_translation, intcomma, intword, naturaldate, naturalday, naturaldelta, naturalsize, naturaltime, ordinal, precisedelta, and scientific must have valid type hints defined for their arguments and return values."
    },
    {
      "id": "m28",
      "text": "The metric function must accept an optional unit string argument to specify the desired unit of measurement. When a unit is provided, the output string should include that unit suffix appropriately formatted."
    },
    {
      "id": "m29",
      "text": "The intcomma function must correctly format numbers with zero decimal places (ndigits=0) by omitting any trailing decimal point or zeros."
    }
  ],
  "closing": "Please ensure all changes are verified against existing tests and that no regressions occur in localization support."
}
